<?php
// Test des migrations : installation neuve → up → données d'exemple → down (retour arrière) → données historiques intactes → up de nouveau.
$tmp = sys_get_temp_dir() . '/symo-mig-' . bin2hex(random_bytes(4)) . '.sqlite'; $cfg = $tmp . '.php';
file_put_contents($cfg, "<?php return ['app_url'=>'http://localhost:8080','db'=>['driver'=>'sqlite','path'=>'$tmp'],'mail_driver'=>'log'];"); putenv("SYMO_CONFIG=$cfg"); define('ROOT', dirname(__DIR__, 2));
require ROOT . '/_app/bootstrap.php';
$res = []; $t = function ($id, $title, $fn) use (&$res) { try { $r = $fn(); $res[] = [$id, $title, $r === true, $r === true ? '' : (string) $r]; } catch (Throwable $e) { $res[] = [$id, $title, false, $e->getMessage()]; } };
$cols = fn($tbl) => array_column(DB::all($tbl === 'x' ? 'SELECT 1' : "PRAGMA table_info($tbl)"), 'name'); $ver = fn() => (int) DB::val("SELECT svalue FROM settings WHERE skey='schema_version'");
$new = ['payments', 'payment_events', 'notifications', 'message_templates', 'order_statuses', 'quote_messages'];
$t('MIG-01', "installation neuve : schéma à jour (v" . SCHEMA_VERSION . ") avec toutes les tables et colonnes", fn() => $ver() === SCHEMA_VERSION && count(array_filter($new, 'DB::tableExists')) === count($new) && in_array('details', $cols('quotes')) && in_array('availability', $cols('products')) && in_array('width', $cols('files')) && in_array('tracking_ref', $cols('orders')) ?: 'schéma incomplet (v' . $ver() . ')');
$t('MIG-02', 'statuts de commande : historiques repris + nouveaux statuts', fn() => (int) DB::val('SELECT COUNT(*) FROM order_statuses') === 13 && DB::val("SELECT COUNT(*) FROM order_statuses WHERE skey IN ('production_done','ready_pickup','out_for_delivery') AND is_system=1") == 3 ?: 'statuts');
// données d'exemple : une commande utilisant un NOUVEAU statut, un utilisateur, un paiement
$uid = DB::ins('users', ['email' => 'mig@test.local', 'password_hash' => 'x', 'name' => 'Mig', 'role' => 'customer']); $oid = DB::ins('orders', ['ref' => 'SP-MIG-0001', 'user_id' => $uid, 'email' => 'mig@test.local', 'name' => 'Mig', 'status' => 'ready_pickup', 'total' => 1000, 'access_token' => 'tok']); DB::ins('payments', ['order_id' => $oid, 'provider' => 'test', 'amount' => 1000, 'idempotency_key' => 'k1']);
$t('MIG-03', 'retour arrière v' . SCHEMA_VERSION . ' → v3 : tables et colonnes ajoutées retirées, version = 3', function () use ($new, $cols, $ver) { migrate_down(3); foreach ($new as $n) if (DB::tableExists($n)) return "table $n encore là"; foreach (['service_type', 'details', 'desired_date'] as $c) if (in_array($c, $cols('quotes'))) return "colonne quotes.$c"; return $ver() === 3 ?: 'version ' . $ver(); });
$t('MIG-04', 'retour arrière : données historiques intactes, commande au statut équivalent (ready_pickup → shipped)', fn() => DB::val("SELECT status FROM orders WHERE ref='SP-MIG-0001'") === 'shipped' && DB::val("SELECT COUNT(*) FROM users WHERE email='mig@test.local'") == 1 && (int) DB::val('SELECT COUNT(*) FROM products') > 40 && (int) DB::val('SELECT COUNT(*) FROM categories') > 15 ?: 'données altérées');
$t('MIG-05', 'application répétée (up) : idempotente, version rétablie, aucune perte', function () use ($new, $ver) { migrate_up(); migrate_up(); foreach ($new as $n) if (!DB::tableExists($n)) return "table $n absente"; return $ver() === SCHEMA_VERSION && DB::val("SELECT status FROM orders WHERE ref='SP-MIG-0001'") === 'shipped' && (int) DB::val('SELECT COUNT(*) FROM order_statuses') === 13 ?: 'état final'; });
$t('MIG-06', 'migration concurrente simulée : « up » exécuté deux fois sans erreur ni doublon', function () { $m = migrations()[4]; $m['up'](); $m['up'](); return (int) DB::val('SELECT COUNT(*) FROM order_statuses') === 13 ?: 'doublons de statuts'; });
foreach ($res as [$id, $title, $ok, $note]) echo ($ok ? '  ✓ ' : '  ✗ ') . "$id $title" . ($ok ? '' : "  → $note") . "\n";
$fails = count(array_filter($res, fn($r) => !$r[2])); echo "\n=== " . (count($res) - $fails) . '/' . count($res) . " tests de migration réussis\n"; @unlink($tmp); @unlink("$tmp-wal"); @unlink("$tmp-shm"); @unlink($cfg); exit($fails ? 1 : 0);
